import{_ as t,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"Configuration (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/configuration/index.md","filePath":"api/graphql-api/admin/configuration/index.md","lastUpdated":1783079210000}'),n={name:"api/graphql-api/admin/configuration/index.md"};function i(d,e,s,l,c,u){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="configuration-admin" tabindex="-1">Configuration (Admin) <a class="header-anchor" href="#configuration-admin" aria-label="Permalink to &quot;Configuration (Admin)&quot;">​</a></h1><p>The admin <strong>Configuration</strong> screen edits Bagisto&#39;s store-wide settings — order settings, currencies, email, SEO, inventory, and everything every installed module adds. Internally these are one flat key/value store; the form layout you see in the admin (Section → Group → Field group → Field) is a <strong>schema</strong> that each module registers at runtime.</p><p>Because that schema has hundreds of fields and grows with every plugin, the API does <strong>not</strong> expose one endpoint per screen. Three generic operations cover the entire Configuration area — current and future:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./menu.html"><code>menuAdminConfigurationMenu</code></a></td><td>Query</td><td><strong>Discover</strong> the schema — which fields exist, their type, default, scoping, validation, and options</td></tr><tr><td><a href="./slugs.html"><code>listAdminConfigurationSlug</code></a></td><td>Query</td><td><strong>List</strong> every slug (section / group key) to pass to Values and Update</td></tr><tr><td><a href="./values.html"><code>valuesAdminConfigurationValues</code></a></td><td>Query</td><td><strong>Read</strong> the current effective values for a slug</td></tr><tr><td><a href="./update.html"><code>createAdminConfigurationUpdate</code></a></td><td>Mutation</td><td><strong>Write</strong> new values for a slug</td></tr></tbody></table><h2 id="how-the-three-work-together" tabindex="-1">How the three work together <a class="header-anchor" href="#how-the-three-work-together" aria-label="Permalink to &quot;How the three work together&quot;">​</a></h2><p>A client edits a section in four steps:</p><ol><li><strong>Discover</strong> — call the Menu query (scoped with <code>slug</code>) to learn the fields under a section: each field&#39;s dotted <code>code</code>, <code>type</code>, whether it is <code>channelBased</code> / <code>localeBased</code>, its <code>validation</code>, and any <code>options</code>.</li><li><strong>Read</strong> — call the Values query for that slug to load the current values into your form.</li><li><strong>Write</strong> — call the Update mutation with the changed <code>code → value</code> map.</li><li><strong>Refresh</strong> — Update returns the re-resolved values, so you can update your form state without another read.</li></ol><p>Or skip steps 1–2 and call the Menu query with <code>include_values: true</code> to get the schema and the current values in a single round trip.</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><ul><li><strong>Slug</strong> — a dotted path (<code>section.group</code>, e.g. <code>sales.order_settings</code>) that scopes a request to one subtree of the schema. Required by Values and Update; optional on Menu (omit it to get the whole tree).</li><li><strong>Code</strong> — the fully-qualified field path (<code>sales.order_settings.reorder.admin</code>). This is the unit you read and write.</li><li><strong>Scoping</strong> — <code>channelBased</code> / <code>localeBased</code> (reported by Menu) decide whether the <code>channel</code> / <code>locale</code> arguments matter for a field. A field with both <code>false</code> is global; passing <code>channel</code> / <code>locale</code> for it is harmless but ignored.</li><li><strong>Values are strings</strong> — the store column is text, so booleans, numbers, and JSON all come back as strings (<code>&quot;1&quot;</code>, <code>&quot;0&quot;</code>, <code>&quot;49.99&quot;</code>).</li><li><strong>Defaults</strong> — a field with no saved value falls back to the schema <code>default</code> reported by Menu.</li></ul><h2 id="rules-to-know" tabindex="-1">Rules to know <a class="header-anchor" href="#rules-to-know" aria-label="Permalink to &quot;Rules to know&quot;">​</a></h2><ul><li><strong>Stay in scope</strong> — every key you write must start with the request&#39;s <code>slug.</code>. You cannot accidentally overwrite a field in another section.</li><li><strong>Validation is server-side</strong> — it is taken from each field&#39;s schema <code>validation</code> (discovered via Menu), never trusted from the client.</li><li><strong>File / image fields</strong> are set via the REST multipart endpoint only — GraphQL has no binary transport.</li><li><strong>Custom fields</strong> — fields reported as <code>type: &quot;custom&quot;</code> are blade-rendered in the admin and are <strong>read-only</strong> through the API.</li><li><strong>Password fields</strong> are masked in the UI but stored as plaintext (a Bagisto core behaviour, not an API limitation).</li></ul><p>All Configuration operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',13)]))}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
